nodes.text:
def D(t):  # двойственность: = ↔ ≠, ∧ ↔ ∨ (без ¬)
    if t == EQ: return NE
    if t == NE: return EQ
    op = {"∧": "∨", "∨": "∧"}[t[0]]
    return (op, D(t[1]), D(t[2]))

def ev(t, v, lo, hi, neg):
    if t == EQ: return v
    if t == NE: return neg(v)
    a, b = ev(t[1], v, lo, hi, neg), ev(t[2], v, lo, hi, neg)
    return min(a, b) if t[0] == "∧" else max(a, b)

